$$\begin{array}{l}
  {\left| {P_{i - 1}P_{i}} \right| = \sqrt{\left( {\Delta x} \right)^{2} + \left( {\Delta y_{i}} \right)^{2}} = \sqrt{\left( {\Delta x} \right)^{2} + {\lbrack{f^{\prime}(x_{i}^{*})\Delta x}\rbrack}^{2}}} \\
  {\phantom{\left| {P_{i - 1}P_{i}} \right|}{= \sqrt{1 + {\lbrack{f^{\prime}(x_{i}^{*})}\rbrack}^{2}}\sqrt{\left( {\Delta x} \right)^{2}} = \sqrt{1 + {\lbrack{f^{\prime}{(x_{i}^{*})}}\rbrack}^{2}}\Delta x\qquad\left( {since}\Delta x > 0 \right)}}
  \end{array}$$

$$\begin{array}{l}
  {F = {\lim\limits_{n\rightarrow\infty}\sum\limits_{i = 1}^{n}{62.5{({7 - y_{i}^{*}})}2\sqrt{9 - {(y_{i}^{*})}^{2}}\Delta y}}} \\
  {\phantom{F} = {125{\int_{- 3}^{3}{\left( {7 - y} \right)\sqrt{9 - y^{2}}dy}}}} \\
  {\phantom{F} = {125 \cdot 7{\int_{- 3}^{3}{\sqrt{9 - y^{2}}dy - 125{\int_{- 3}^{3}{y\sqrt{9 - y^{2}}dy}}}}}}
  \end{array}$$

$$\begin{array}{ccl}
  \overline{x} & = & {\frac{1}{A}{\int_{0}^{1}{x\lbrack f\left( x) - g(x) \right\rbrack}}dx = \frac{1}{\frac{1}{6}}{\int_{0}^{1}{x(x - x^{2})dx}}} \\
   & = & {6{\int_{0}^{1}{(x^{2} - x^{3})}}dx = 6\left\lbrack {\frac{x^{3}}{3} - \frac{x^{4}}{4}} \right\rbrack_{0}^{1} = \frac{1}{2}} \\
  \overline{y} & = & {\frac{1}{A}{\int_{0}^{1}{\frac{1}{2}\left\{ \left\lbrack f(x) \right\rbrack^{2} - \left\lbrack g(x) \right\rbrack^{2} \right\}}}dx = \frac{1}{\frac{1}{6}}{\int_{0}^{1}{\frac{1}{2}(x^{2} - x^{4})dx}}} \\
   & = & {3\left\lbrack {\frac{x^{3}}{3} - \frac{x^{5}}{5}} \right\rbrack_{0}^{1} = \frac{2}{5}}
  \end{array}$$

$$\begin{array}{l}
  {F = {\lim\limits_{n\rightarrow^{}\infty}\sum\limits_{i = 1}^{n}{2\pi r_{i}}\upsilon\left( r_{i} \right)\Delta r = {\int_{0}^{R}{2\pi r}}\upsilon(r)dr}} \\
  {\phantom{F} = {{\int_{0}^{R}{2\pi r}}\frac{P}{4\eta l}{({R^{2} - r^{2}})}^{}dr}} \\
  {\phantom{F} = {\frac{\pi P}{2\eta l}{\int_{0}^{R}{({R^{2}r - r^{3}})}}^{}dr = \frac{\pi P}{2\eta l}\left\lbrack {R^{2}\frac{r^{2}}{2} - \frac{r^{4}}{4}} \right\rbrack_{r = 0}^{r = R}}} \\
  {\phantom{F} = {\frac{\pi P}{2\eta l}\left\lbrack {\frac{R^{4}}{2} - \frac{R^{4}}{4}} \right\rbrack = \frac{\pi PR^{4}}{8\eta l}}}
  \end{array}$$

$$\begin{array}{ll}
  {{{\int_{0}^{\infty}{tce^{- ct}}}dt} = {\lim\limits_{x\rightarrow\infty}{\int_{0}^{x}{tce^{- ct}}}dt = \lim\limits_{x\rightarrow\infty}\left( {\left. {- te^{- ct}} \right\rbrack_{0}^{x} + {\int_{0}^{x}e^{- ct}}dt} \right)}} & \\
  {\phantom{{\int_{0}^{\infty}{tce^{- ct}}}dt} = {\lim\limits_{x\rightarrow\infty}\left( {- xe^{- cx} + \frac{1}{c} - \frac{e^{- cx}}{c}} \right) = \frac{1}{c}}} & {\qquad\begin{array}{l}
  \text{(The limit of the first term is~} \\
  {0\text{~by l’Hospital’s Rule.)}}
  \end{array}}
  \end{array}$$

$$\begin{array}{l}
  {{P\left( {0 \leqslant T \leqslant 1} \right)} = {{\int_{0}^{1}{f(t)}}dt}} \\
  {\phantom{P\left( {0 \leqslant T \leqslant 1} \right)} = {{\int_{0}^{1}{0.2e^{- t/5}}}dt = 0.2\left. {\left( {- 5} \right)e^{- t/5}} \right\rbrack_{0}^{1}}} \\
  {\phantom{P\left( {0 \leqslant T \leqslant 1} \right)} = {1 - e^{- 1/5} \approx 0.1813}}
  \end{array}$$
